    private void beginGrid(Minecraft client){
        require(craftIndex>=0 && craftIndex<=11,"bounded eleven paid crafts plus ONE ordinary earned-phial binding");
        var clicks=new ArrayList<int[]>();var types=new LinkedHashSet<Item>();for(int cell=0;cell<9;cell++)if(ingredient(cell,craftIndex)!=Items.AIR)types.add(ingredient(cell,craftIndex));
        for(Item item:types){var cells=new ArrayList<Integer>();for(int cell=0;cell<9;cell++)if(ingredient(cell,craftIndex)==item)cells.add(cell);int used=0;for(int slot=0;slot<36 && used<cells.size();slot++){ItemStack actual=client.player.getInventory().getItem(slot);if(!actual.is(item) || craftIndex==11 && item==filledPhial() && !firePhial(actual))continue;int from=playerSlot(client,slot),take=Math.min(actual.getCount(),cells.size()-used);clicks.add(new int[]{from,0});for(int n=0;n<take;n++)clicks.add(new int[]{cells.get(used++)+2,1});clicks.add(new int[]{from,0});}require(used==cells.size(),"ACTUAL split physical inputs cover recipe cells "+item);}
        gridClicks=List.copyOf(clicks);gridIndex=0;onServer(client,()->preflight(serverPlayer(client)));next(Step.GRID);
    }
