    private AABB patchBounds(){return new AABB(Vec3.atLowerCornerOf(patchMin()),Vec3.atLowerCornerOf(patchMax().offset(1,1,1)));}
    private void patch(ServerLevel level){
        for(int x=patchMin().getX()>>4;x<=patchMax().getX()>>4;x++)for(int z=patchMin().getZ()>>4;z<=patchMax().getZ()>>4;z++)level.getChunk(x,z);require(level.getEntitiesOfClass(ItemEntity.class,patchBounds()).isEmpty() && level.getEntitiesOfClass(ExperienceOrb.class,patchBounds()).isEmpty() && level.getEntitiesOfClass(LivingEntity.class,patchBounds()).isEmpty() && pendingStacks(level).isEmpty(),"new patch refuses all old entities/items/pending/XP");for(BlockPos at:BlockPos.betweenClosed(patchMin(),patchMax()))require(level.getBlockEntity(at)==null && !BuiltInRegistries.BLOCK.getKey(level.getBlockState(at).getBlock()).getNamespace().equals("thaumcraft") && !oldBlocks.containsKey(at),"never overwrite old BE/TC/scanned cells "+at);for(BlockPos at:BlockPos.betweenClosed(patchMin(),patchMax()))level.setBlockAndUpdate(at,at.getY()<bench.getY()?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState());
        // ONLY declared mundane platforms/supports, not automation or outputs.
        for(int x=furnacePos.getX()-4;x<=furnacePos.getX()+4;x++)for(int z=furnacePos.getZ()-4;z<=furnacePos.getZ()+4;z++)if(z<=furnacePos.getZ()-2 || z>=furnacePos.getZ()+2)for(int y=bench.getY();y<cfPos.getY();y++)level.setBlockAndUpdate(new BlockPos(x,y,z),Blocks.STONE.defaultBlockState());
        for(BlockPos at:jarPositions)for(int y=bench.getY();y<at.getY();y++)level.setBlockAndUpdate(new BlockPos(at.getX(),y,at.getZ()),Blocks.STONE.defaultBlockState());for(int y=bench.getY();y<leverPos.getY();y++)level.setBlockAndUpdate(new BlockPos(leverPos.getX(),y,leverPos.getZ()),Blocks.STONE.defaultBlockState());
    }
    private int supply(ServerPlayer player,Item item,int n,String purpose){require(item==Items.IRON_INGOT && n==9 || item==Items.GLASS && n==2 || item==Items.GOLD_NUGGET && n==2 || item==Items.GOLD_INGOT && n==3 || (item==silverwood() || item==greatwood() || item==Items.STONE || item==Items.BUCKET || item==Items.PISTON) && n==1 || item==Items.LEVER && n==4 || item==Items.COAL && (n==4 || n==1),"ONLY exact declared RAW fixtures, never finished devices/vis/essentia/XP");int slot=emptyMain(player);player.getInventory().setItem(slot,new ItemStack(item,n));inputs.add(Map.of("raw_item",BuiltInRegistries.ITEM.getKey(item).toString(),"count",n,"purpose",purpose,"genuinely_empty_main_slot",slot));return slot;}
    private List<ItemStack> physicalStacks(ServerPlayer player){var result=new ArrayList<ItemStack>();result.addAll(player.getInventory().items);result.addAll(player.getInventory().offhand);result.add(player.containerMenu.getCarried());var table=table(player.level());for(int cell=0;cell<9;cell++)result.add(table.getItem(cell));result.add(table.getItem(TileArcaneWorkbench.WAND_SLOT));for(ItemEntity item:player.serverLevel().getEntitiesOfClass(ItemEntity.class,patchBounds()))result.add(item.getItem());result.addAll(pendingStacks(player.serverLevel()));return result;}
    private static Map<String,Integer> itemAspects(List<ItemStack> stacks){var result=new LinkedHashMap<String,Integer>();for(ItemStack value:stacks){if(ItemJar.isJar(value))merge(result,ItemJar.getAspect(value),ItemJar.getAmount(value)*value.getCount());if(value.is(filledPhial())){var data=ItemEssence.data(value);require(data!=null && Aspect.getAspect(data.tag())!=null,"actual filled-phial component");merge(result,Aspect.getAspect(data.tag()),PhialData.AMOUNT*value.getCount());}}return Map.copyOf(result);}
    @SuppressWarnings("unchecked") private List<ItemStack> pendingStacks(ServerLevel level){try{var field=DeferredItemDrops.class.getDeclaredField("FACTORY");field.setAccessible(true);var factory=(SavedData.Factory<DeferredItemDrops>)field.get(null);var queue=level.getDataStorage().get(factory,"thaumcraft_pending_inventory_drops");if(queue==null)return List.of();var result=new ArrayList<ItemStack>();for(Tag raw:queue.save(new CompoundTag(),level.registryAccess()).getList("Pending",Tag.TAG_COMPOUND)){CompoundTag row=(CompoundTag)raw;if(!patchBounds().contains(Vec3.atCenterOf(BlockPos.of(row.getLong("Source")))))continue;ItemStack value=ItemStack.parse(level.registryAccess(),row.getCompound("Stack")).orElseThrow();value.setCount(row.getInt("Count"));result.add(value);}return result;}catch(ReflectiveOperationException error){throw new IllegalStateException("Read-only native pending-output view needs reconciliation",error);}}

    private void capture(int index){require(captures==index,"exact contiguous capture order130-137");++captures;report.put("actual_captures_requested",captures);capture.accept(CAPTURES.get(index));}
    @SuppressWarnings("unchecked") private static List<GuiMessage> chat(Minecraft client)throws ReflectiveOperationException{return List.copyOf((List<GuiMessage>)BookClientSmoke.field(client.gui.getChat(),"allMessages"));}
    private boolean hand(Minecraft client,Predicate<ItemStack> wanted)throws ReflectiveOperationException{require(client.player.containerMenu==client.player.inventoryMenu,"native hand SWAP outside menus only");if(!wanted.test(client.player.getInventory().getItem(HAND_SLOT))){click(client,playerSlot(client,itemSlot(client.player,wanted)),HAND_SLOT,ClickType.SWAP);handChangedAt=client.player.tickCount;return false;}if(client.player.tickCount-handChangedAt<6)return false;select(client,HAND_SLOT);return true;}
    private boolean emptyHand(Minecraft client)throws ReflectiveOperationException{return hand(client,ItemStack::isEmpty);}
    private static void select(Minecraft client,int slot)throws ReflectiveOperationException{client.player.getInventory().selected=slot;var ensure=client.gameMode.getClass().getDeclaredMethod("ensureHasSentCarriedItem");ensure.setAccessible(true);ensure.invoke(client.gameMode);}
    private static int playerSlot(Minecraft client,int inventory){return client.player.containerMenu.slots.stream().filter(slot->slot.container==client.player.getInventory() && slot.getContainerSlot()==inventory).findFirst().orElseThrow().index;}
    private static void click(Minecraft client,int slot,int button,ClickType type){client.gameMode.handleInventoryMouseClick(client.player.containerMenu.containerId,slot,button,type,client.player);}
    private static void sendRotation(Minecraft client,Vec3 point){lookAt(client,point);client.player.connection.send(new ServerboundMovePlayerPacket.Rot(client.player.getYRot(),client.player.getXRot(),client.player.onGround()));}
    private boolean aimReady(Minecraft client,BlockPos pos,Direction face,Vec3 point){require(client.player.canInteractWithBlock(pos,0),"actual native Survival reach "+pos);sendRotation(client,point);if(!pos.equals(useAimPos) || face!=useAimFace || !point.equals(useAimPoint)){useAimPos=pos.immutable();useAimFace=face;useAimPoint=point;useAimStarted=client.player.tickCount;return false;}return client.player.tickCount-useAimStarted>=6;}
    private boolean use(Minecraft client,BlockPos pos,Direction face,Vec3 point){if(!aimReady(client,pos,face,point))return false;require(client.gameMode.useItemOn(client.player,InteractionHand.MAIN_HAND,new BlockHitResult(point,face,pos,false)).consumesAction(),"actual native useItemOn accepted "+pos+"/"+face);clearAim();return true;}
    private void clearAim(){useAimPos=null;useAimFace=null;useAimPoint=null;}
    private static void lookAt(Minecraft client,Vec3 point){Vec3 delta=point.subtract(client.player.getEyePosition());client.player.setYRot((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)));client.player.yRotO=client.player.getYRot();client.player.setXRot((float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z))));client.player.xRotO=client.player.getXRot();}
    private static void stand(ServerPlayer player,double x,double y,double z){var body=new AABB(x-.3,y+.001,z-.3,x+.3,y+1.8,z+.3);BlockPos floor=BlockPos.containing(x,y-.01,z);require(player.level().noCollision(player,body) && !player.level().getBlockState(floor).getCollisionShape(player.level(),floor).isEmpty(),"collision-checked camera above actual existing declared support");player.teleportTo(x,y,z);}
    private void frontCamera(ServerPlayer player){stand(player,furnacePos.getX()+.5,cfPos.getY(),furnacePos.getZ()-3.1);}
    private void powerCamera(ServerPlayer player){stand(player,leverPos.getX()+.5,cfPos.getY(),leverPos.getZ()+2.6);}
    private void connectorCamera(ServerPlayer player,int index){stand(player,bufferPos.getX()+(index==0?-2:3),cfPos.getY(),bufferPos.getZ()-3);}
    // Ground-level one-block aisle avoids looking THROUGH the raised platform
    // at the low furnace. Body fits between platform south edge and furnace.
    private void sourceMenuCamera(ServerPlayer player){stand(player,furnacePos.getX()+.5,bench.getY(),furnacePos.getZ()-.5);}
    private void demoCamera(ServerPlayer player){stand(player,demoPos.getX()+.5,bench.getY(),demoPos.getZ()-2.6);}
    private Vec3 armPoint(Direction side){return Vec3.atCenterOf(bufferPos).add(side.getStepX()*.35,0,0);}
    private Vec3 leverPoint(){return Vec3.atCenterOf(leverPos).add(0,-.25,.15);}
    private static Vec3 jarPoint(BlockPos at){return Vec3.atCenterOf(at).add(0,-.1,-.3125);}
    private static void releaseKeys(Minecraft client){client.options.keyUse.setDown(false);client.options.keyAttack.setDown(false);client.options.keyShift.setDown(false);}
    private void releaseInputs(Minecraft client){releaseUse(client);aimCharge=false;ClientTickEvent.CLIENT_PRE.unregister(chargeGuard);releaseKeys(client);if(client.player!=null && client.gameMode!=null)client.gameMode.stopDestroyBlock();if(previousCamera!=null)client.options.setCameraType(previousCamera);}
    private static BlockPos serverSessionNode(ServerPlayer player,ItemStack wand){try{var field=ItemWandCasting.class.getDeclaredField("SERVER_NODE_USES");field.setAccessible(true);Object session=((Map<?,?>)field.get(null)).get(player);require(session!=null && BookClientSmoke.field(session,"hand")==InteractionHand.MAIN_HAND && BookClientSmoke.field(session,"stack")==wand,"actual SERVER-owned node session exact hand/stack");return ((BlockPos)BookClientSmoke.field(session,"pos")).immutable();}catch(ReflectiveOperationException error){throw new IllegalStateException("Read-only native node-session view needs reconciliation",error);}}
    private static boolean sameExceptVis(ItemStack first,ItemStack second){WandData aData=ItemWandCasting.data(first),bData=ItemWandCasting.data(second);if(!aData.rod().equals(bData.rod()) || !aData.cap().equals(bData.cap()))return false;ItemStack a=first.copy(),b=second.copy();a.remove(ThaumcraftContent.WAND_DATA.get());b.remove(ThaumcraftContent.WAND_DATA.get());return ItemStack.matches(a,b);}
    private static void verifyDebit(ItemStack before,ItemStack after,Map<String,Integer> price){require(sameExceptVis(before,after),"all actual payer non-vis/material/focus/craft-cost components exact");for(String tag:WandData.PRIMALS)require(ItemWandCasting.data(before).amount(tag)-ItemWandCasting.data(after).amount(tag)==price.getOrDefault(tag,0),"EXACT actual finite centivis price "+tag);}
    private static CompoundTag beTag(BlockEntity tile){return tile.saveWithFullMetadata(tile.getLevel().registryAccess()).copy();}
    private static CompoundTag stableNodeTag(BlockEntity tile){CompoundTag tag=beTag(tile);tag.remove("Aspects");tag.remove("lastActive");return tag;}
    private static String tag(Aspect aspect){return aspect==null?"":aspect.getTag();}
    private static Map<String,Integer> aspects(AspectList list){var result=new LinkedHashMap<String,Integer>();for(Aspect type:list.getAspects())merge(result,type,list.getAmount(type));return Map.copyOf(result);}
    private static Map<String,Integer> singleton(Aspect type,int amount){var result=new LinkedHashMap<String,Integer>();merge(result,type,amount);return Map.copyOf(result);}
    private static int sum(Map<String,Integer> values){return values.values().stream().mapToInt(Integer::intValue).sum();}
    private static int amount(Frame frame,String location,String tag){return frame.locations().getOrDefault(location,Map.of()).getOrDefault(tag,0);}
    private static void merge(Map<String,Integer> target,Aspect type,int amount){require(amount>=0 && (amount==0 || type!=null),"real stored amounts never contain negative filter marker/untyped units");if(amount>0)target.merge(type.getTag(),amount,Integer::sum);}
    private static boolean gold(ItemStack value){return value.is(ThaumcraftContent.WAND.get()) && ItemWandCasting.data(value).rod().equals("greatwood") && ItemWandCasting.data(value).cap().equals("gold");}
    private static boolean primary(ItemStack value){return value.is(ThaumcraftContent.WAND.get()) && ItemWandCasting.data(value).rod().equals("silverwood") && ItemWandCasting.data(value).cap().equals("thaumium");}
    private static boolean potPhial(ItemStack value){return value.is(filledPhial()) && ItemEssence.data(value)!=null && ItemEssence.data(value).tag().equals("potentia");}
    private static boolean firePhial(ItemStack value){return value.is(filledPhial()) && ItemEssence.data(value)!=null && ItemEssence.data(value).tag().equals("ignis");}
    private static int itemSlot(Player player,Predicate<ItemStack> wanted){for(int slot=0;slot<36;slot++)if(wanted.test(player.getInventory().getItem(slot)))return slot;throw new IllegalStateException("Missing actual finite centrifuge input/output");}
    private static ItemStack stack(Player player,Predicate<ItemStack> wanted){return player.getInventory().getItem(itemSlot(player,wanted));}
    private static int count(Player player,Item item){return player.getInventory().items.stream().mapToInt(value->countStack(value,item)).sum();}
    private static int countStack(ItemStack value,Item item){return value.is(item)?value.getCount():0;}
    private static int emptyMain(Player player){for(int slot=9;slot<36;slot++)if(player.getInventory().getItem(slot).isEmpty())return slot;throw new IllegalStateException("No genuinely empty main inventory slot");}
    private static Item tubeItem(){return ThaumcraftTubes.ESSENTIA_TUBE_ITEM.get();}
    private static Item valveItem(){return ThaumcraftTubes.ESSENTIA_VALVE_ITEM.get();}
    private static Item restrictItem(){return ThaumcraftTubes.ESSENTIA_RESTRICT_ITEM.get();}
    private static Item bufferItem(){return ThaumcraftTubes.ESSENTIA_BUFFER_ITEM.get();}
    private static Item cfItem(){return ThaumcraftTubes.CENTRIFUGE_ITEM.get();}
    private static Item constructItem(){return ThaumcraftDistillation.ALCHEMICAL_CONSTRUCT_ITEM.get();}
    private static Item material(String name){return ThaumcraftContent.MATERIALS.get(name).get();}
    private static Item labelItem(){return material("jar_label");}
    private static Item filledPhial(){return ThaumcraftContent.FILLED_PHIAL.get();}
    private static Item emptyPhial(){return ThaumcraftContent.EMPTY_PHIAL.get();}
    private static Item silverwood(){return ThaumcraftNaturals.SILVERWOOD_PLANKS.get().asItem();}
    private static Item greatwood(){return ThaumcraftNaturals.GREATWOOD_PLANKS.get().asItem();}
