    private TileTubeBuffer buffer(Level level){return (TileTubeBuffer)level.getBlockEntity(bufferPos);}
    private TileTube connector(Level level,int index){return (TileTube)level.getBlockEntity(connectorPositions.get(index));}
    private TileJar jar(Level level,int index){return (TileJar)level.getBlockEntity(jarPositions.get(index));}
    private TileAlchemyFurnace oven(Level level){return (TileAlchemyFurnace)level.getBlockEntity(furnacePos);}
    private TileAlembic alembic(Level level){return (TileAlembic)level.getBlockEntity(furnacePos.above());}
    private TileArcaneWorkbench table(Level level){return (TileArcaneWorkbench)level.getBlockEntity(bench);}
